<?php class CarreraModel {private PDO $pdo;function __construct(PDO $pdo){$this->pdo=$pdo;}function obtenerTodas(){return $this->pdo->query('SELECT * FROM carreras ORDER BY nombre_carrera')->fetchAll();}function crear($d){$s=$this->pdo->prepare('INSERT INTO carreras(nombre_carrera) VALUES(?)');return $s->execute([$d['nombre_carrera']]);}function obtenerPorId($id){$s=$this->pdo->prepare('SELECT * FROM carreras WHERE id_carrera=?');$s->execute([$id]);return $s->fetch();}function editar($id,$d){$s=$this->pdo->prepare('UPDATE carreras SET nombre_carrera=? WHERE id_carrera=?');return $s->execute([$d['nombre_carrera'],$id]);}function eliminar($id){$s=$this->pdo->prepare('DELETE FROM carreras WHERE id_carrera=?');return $s->execute([$id]);}}
